<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {Sparkles,ArrowUp,X,Settings2,Check,CheckCircle2,ChevronDown,ChevronRight,LoaderCircle,Square,RotateCcw,Eye,ArrowUpRight,ShieldCheck,Activity,Plus,Trash2,RefreshCw,KeyRound,AlertCircle,Layers,MousePointer2,Play,Copy,Download} from 'lucide-vue-next';
import {isStaticHosting} from '../../paths.js';import {providers,providerById,DEFAULT_MODEL} from '../agent/providers.js';
import {runDesignAgent,agentRequest,inspectCanvas,waitForCode} from '../agent/runtime.js';import {agentTools} from '../agent/contracts.js';import {openAgentService} from '../agent/bridge.js';
import {projectFingerprint} from '../agent/state.js';
import {storeGet,storePut} from '../storage.js';import AgentMessage from './AgentMessage.vue';import './agent-panel.css';
const props=defineProps({project:Object,revision:Number,selectedIds:Array,visible:Boolean,applyDesign:Function});const emit=defineEmits(['close','draft','busy','preview','notify']);
const tab=ref('chat'),prompt=ref(''),messages=ref([]),tools=ref([]),result=ref(null),brief=ref(null),report=ref(null),busy=ref(false),applying=ref(false),stage=ref('idle'),status=ref('准备好，开始你的下一个作品。'),round=ref(0),usage=ref({input:0,output:0}),baseRevision=ref(-1),error=ref(''),notice=ref(''),settings=ref(null),loadingSettings=ref(false),settingsError=ref(''),settingsBusy=ref(false),models=ref([]),model=ref(DEFAULT_MODEL),profileId=ref(''),connection=ref(null),formOpen=ref(false),form=ref({}),content=ref(null),input=ref(null),bridging=ref(false),applied=ref(false);let abort,saveTimer,disposed=false,projectId=props.project.id,draftProjectId=projectId;
const conflict=computed(()=>!applied.value&&(baseRevision.value===-2||baseRevision.value>=0&&props.revision!==baseRevision.value));
const profile=computed(()=>settings.value?.profiles.find(p=>p.id===profileId.value));const completeTools=computed(()=>tools.value.filter(t=>t.state==='done').length);const canApply=computed(()=>!!result.value?.modified&&!busy.value&&!applying.value&&!applied.value&&!conflict.value&&report.value?.errors?.length===0);
const suggestions=[{label:'新能源智慧园区',prompt:'创建新能源智慧园区大屏，深蓝银白风格，中间保留大面积园区 3D 场景，重点展示光伏发电、园区能耗和充电设施，添加光伏阵列、充电桩与可交互设备标签。使用演示数据。'},{label:'工业设备监测',prompt:'创建工业设备监测大屏，石墨钛金风格，重点突出设备效率、产能与告警，在原有车间场景添加机械臂和水泵，点击设备显示运行数据。'},{label:'精修当前作品',prompt:'保留现有业务内容与 3D 场景，精修当前大屏的标题层级、间距、配色与图表，减少多余辉光，检查遮挡与越界。'}];
const toolLabels={get_code_api:'读取编程接口',list_code_files:'查看代码工作区',read_code_file:'读取源代码',write_code_files:'编写前端代码',edit_code_file:'精确修改代码',delete_code_file:'删除代码文件',run_code:'编译与实际运行',restore_code_checkpoint:'恢复代码检查点',get_project_context:'读取画布上下文',get_component_schema:'查询组件参数',get_widget:'读取组件配置',plan_design:'制定设计方案',create_dashboard:'搭建行业布局',configure_canvas:'配置主题与背景',add_widget:'添加可编辑组件',update_widgets:'批量精修组件',arrange_widgets:'编排与对齐',remove_widgets:'精简组件',set_static_data:'配置演示数据',bind_data_source:'绑定数据源',configure_header:'精调 Header',add_scene_objects:'向原场景添加对象',update_scene_objects:'精修场景与标签',configure_events:'配置交互联动',evaluate_design:'评估设计与运行状态',repair_layout:'修正布局问题'};
function persist(){clearTimeout(saveTimer);const id=projectId;saveTimer=setTimeout(()=>storePut('settings',{id:'agent-chat:'+id,value:messages.value.slice(-16).map(m=>({role:m.role,content:m.content.slice(0,5000)}))}).catch(()=>{}),500);}
function scrollBottom(){nextTick(()=>{if(content.value)content.value.scrollTop=content.value.scrollHeight;});}
async function loadSettings(){if(isStaticHosting)return;loadingSettings.value=true;settingsError.value='';try{settings.value=await agentRequest('settings');profileId.value=settings.value.activeProfile;model.value=(await storeGet('settings','agent-model:'+profileId.value))?.value||profile.value?.model||DEFAULT_MODEL;}catch(e){settingsError.value=e.message;if(e.status===401)settings.value={signInRequired:true,signInUrl:'/signin-with-chatgpt?return_to=%2F%3Fassistant%3D1',profiles:[]};}finally{loadingSettings.value=false;}}
async function selectProfile(){const p=profile.value;model.value=(await storeGet('settings','agent-model:'+profileId.value).catch(()=>null))?.value||p?.model||'';models.value=[];connection.value=null;if(!isStaticHosting&&profileId.value)try{await agentRequest('settings',{activeProfile:profileId.value});}catch(e){settingsError.value=e.message;}}
function editProfile(p){form.value={id:p?.managed?undefined:p?.id,name:p?.name||'',provider:p?.provider||'openrouter',baseUrl:p?.baseUrl||providerById('openrouter').baseUrl,model:p?.model||DEFAULT_MODEL,apiKey:''};formOpen.value=true;connection.value=null;}
function changeProvider(){const p=providerById(form.value.provider);form.value.baseUrl=p.baseUrl;form.value.model=p.model;form.value.apiKey='';if(!form.value.name)form.value.name=p.name;}
async function saveProfile(){settingsBusy.value=true;settingsError.value='';try{settings.value=await agentRequest('settings',{profile:form.value});profileId.value=settings.value.activeProfile;model.value=profile.value?.model||'';form.value.apiKey='';formOpen.value=false;connection.value={ok:true,message:'模型配置已加密保存'};}catch(e){settingsError.value=e.message;}finally{settingsBusy.value=false;}}
async function removeProfile(){if(!profile.value||profile.value.managed)return;settingsBusy.value=true;try{settings.value=await agentRequest('settings',{remove:profileId.value});profileId.value=settings.value.activeProfile;model.value=profile.value?.model||DEFAULT_MODEL;}catch(e){settingsError.value=e.message;}finally{settingsBusy.value=false;}}
async function fetchModels(){if(!profileId.value)return;settingsBusy.value=true;settingsError.value='';try{const r=await agentRequest('models',{profileId:profileId.value,model:model.value});models.value=r.models;if(!models.value.length)settingsError.value='厂商未返回模型列表，可直接填写模型 ID';}catch(e){settingsError.value=e.message+'；仍可手动填写模型 ID';}finally{settingsBusy.value=false;}}
async function testConnection(){settingsBusy.value=true;connection.value=null;settingsError.value='';try{const r=await agentRequest('test',{profileId:profileId.value,model:model.value});connection.value={ok:r.ok,message:r.ok?'连接成功，函数工具调用通过':'模型已连接，但没有返回工具调用；请选择支持工具的模型'};}catch(e){connection.value={ok:false,message:e.message};}finally{settingsBusy.value=false;}}
function chooseSuggestion(s){prompt.value=s.prompt;input.value?.focus();}
async function event(e){if(disposed)return;switch(e.type){case 'stage':stage.value=e.stage;status.value=e.label;break;case 'round':round.value=e.round;break;case 'usage':usage.value=e.tokens;break;case 'notice':notice.value=e.message;break;case 'assistant':notice.value=e.content.slice(0,350);break;case 'brief':brief.value=e.brief;break;case 'evaluation':report.value=e.report;break;case 'tool-start':tools.value.push({id:e.id,name:e.name,args:e.args,state:'running',open:false});break;case 'tool-result':{const t=tools.value.find(t=>t.id===e.id);if(t)Object.assign(t,{state:e.ok?'done':'error',result:e.result,duration:e.duration});break;}}}
async function run(){if(busy.value||!prompt.value.trim())return;if(isStaticHosting){await bridge();return;}if(!profileId.value||!model.value){tab.value='settings';settingsError.value='请先选择一个可用的模型配置';return;}
 const text=prompt.value.trim(),base=JSON.parse(JSON.stringify(props.project)),selected=[...props.selectedIds],conversation=[...messages.value];draftProjectId=base.id;baseRevision.value=props.revision;applied.value=false;result.value=null;report.value=null;brief.value=null;error.value='';notice.value='';tools.value=[];round.value=0;usage.value={input:0,output:0};busy.value=true;emit('busy',true);prompt.value='';tab.value='chat';messages.value.push({role:'user',content:text});persist();scrollBottom();abort=new AbortController();
 try{const r=await runDesignAgent({project:base,selectedIds:selected,mode:'auto',scope:'all',prompt:text,profileId:profileId.value,model:model.value,history:conversation,signal:abort.signal,onEvent:event,onDraft:async p=>{if(disposed||props.project.id!==base.id)return;emit('draft',{project:p,baseRevision:baseRevision.value});await nextTick();},inspect:async (p,options)=>{await nextTick();if(options?.codeNodeId)return waitForCode(options,abort.signal);await new Promise(r=>setTimeout(r,150));return inspectCanvas(p);}});result.value=r;report.value=r.report;await saveDraft(base,r);messages.value.push({role:'assistant',content:r.summary||'草稿已生成，配置与运行检查已完成。请预览后应用。'});}
 catch(e){if(e.partial){result.value=e.partial;report.value=e.partial.report;await saveDraft(base,e.partial);}error.value=abort.signal.aborted?'已停止，完成的部分已保留。':e.message;stage.value=abort.signal.aborted?'stopped':'error';status.value=error.value;messages.value.push({role:'assistant',content:error.value});}
 finally{busy.value=false;emit('busy',false);persist();scrollBottom();}}
async function apply(){if(!canApply.value)return;const savedDraftId=draftProjectId;applying.value=true;error.value='';try{await props.applyDesign({project:result.value.project,baseRevision:baseRevision.value,mode:result.value.mode||'auto'});applied.value=true;baseRevision.value=-1;await storePut('settings',{id:'agent-draft:'+savedDraftId,value:null}).catch(()=>{});status.value='作品已应用，所有组件仍可继续编辑';emit('draft',null);}catch(e){error.value=e.message;}finally{applying.value=false;}}
function discard(){if(busy.value)return;storePut('settings',{id:'agent-draft:'+draftProjectId,value:null}).catch(()=>{});emit('draft',null);result.value=null;report.value=null;baseRevision.value=-1;stage.value='idle';status.value='草稿已收起，原稿保持不变';}
async function bridge(){bridging.value=true;try{await openAgentService(JSON.parse(JSON.stringify(props.project)),{prompt:prompt.value});emit('notify','当前项目和本机素材已带入完整服务版');}catch(e){emit('notify',e.message);}finally{bridging.value=false;}}
watch(()=>props.project.id,async id=>{if(projectId===id)return;abort?.abort();clearTimeout(saveTimer);projectId=id;if(applying.value){persist();return;}messages.value=[];if(!applying.value){emit('draft',null);result.value=null;report.value=null;baseRevision.value=-1;}try{const saved=await storeGet('settings','agent-chat:'+id);if(projectId===id)messages.value=saved?.value||[];}catch{}});
watch(model,value=>{if(profileId.value&&value.trim())storePut('settings',{id:'agent-model:'+profileId.value,value:value.trim()}).catch(()=>{});});
watch(()=>props.visible,value=>{if(value)nextTick(()=>input.value?.focus());});
function consumeIntent(){try{const intent=JSON.parse(sessionStorage.getItem('astra:agent-intent')||'null');if(intent){prompt.value=intent.prompt;sessionStorage.removeItem('astra:agent-intent');}}catch{}}
async function saveDraft(base,value){try{await storePut('settings',JSON.parse(JSON.stringify({id:'agent-draft:'+base.id,value:{result:value,baseProject:projectFingerprint(base),mode:value.mode||'auto',tools:tools.value,usage:usage.value,round:round.value}})));}catch{notice.value='本机草稿存储不可用，请在关闭页面前应用或导出作品。';}}
onMounted(async()=>{window.addEventListener('astra:agent-intent',consumeIntent);consumeIntent();loadSettings();try{const id=projectId,saved=await storeGet('settings','agent-chat:'+id);if(projectId!==id)return;if(!messages.value.length)messages.value=saved?.value||[];const draft=await storeGet('settings','agent-draft:'+id);if(projectId!==id)return;if(draft?.value?.result){draftProjectId=id;result.value=draft.value.result;report.value=result.value.report;brief.value=result.value.brief;tools.value=draft.value.tools||[];usage.value=draft.value.usage||result.value.tokens||{input:0,output:0};round.value=draft.value.round||result.value.rounds||0;let same=false;try{same=projectFingerprint(props.project)===projectFingerprint(JSON.parse(draft.value.baseProject));}catch{}baseRevision.value=same?props.revision:-2;if(same)emit('draft',{project:result.value.project,baseRevision:baseRevision.value});else error.value='已恢复上次草稿，但原项目已经变化，请重新生成以保留手动修改';status.value='已恢复上次生成的草稿';}}catch{}});
onBeforeUnmount(()=>{window.removeEventListener('astra:agent-intent',consumeIntent);disposed=true;abort?.abort();clearTimeout(saveTimer);form.value.apiKey='';});
</script>
<template><aside v-show="visible" class="aw-agent-panel" aria-label="大屏设计智能体"><header class="aa-heading"><span class="aa-orb"><Sparkles :size="18" :stroke-width="1.5"/></span><div><strong>Astra Copilot</strong><small>把想法，变成可探索的空间。</small></div><button class="aa-icon" aria-label="关闭智能体面板" @click="emit('close')"><X :size="17"/></button></header>
 <nav class="aa-tabs" aria-label="智能体导航"><button v-for="t in [{id:'chat',name:'创作',icon:Sparkles},{id:'execution',name:'执行',icon:Activity},{id:'settings',name:'模型',icon:Settings2}]" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id"><component :is="t.icon" :size="13"/>{{t.name}}<i v-if="t.id==='execution'&&tools.length">{{completeTools}}/{{tools.length}}</i></button></nav>
 <div ref="content" class="aa-content"><template v-if="tab==='chat'">
  <div v-if="!messages.length" class="aa-welcome"><span class="aa-eyebrow">YOUR CREATIVE PARTNER</span><h2>从一个想法开始，<br/>让数据拥有形状。</h2><p>描述业务、风格与重点，助手会调用设计器工具，构建、检查并精修你的作品。</p><div class="aa-suggestions"><button v-for="s in suggestions" :key="s.label" @click="chooseSuggestion(s)"><span><Sparkles :size="12"/>{{s.label}}</span><ArrowUpRight :size="13"/></button></div><div class="aa-capabilities"><span><Layers :size="12"/>原生组件</span><span><MousePointer2 :size="12"/>场景与交互</span><span><ShieldCheck :size="12"/>可预览撤销</span></div></div>
  <div v-for="(m,i) in messages" :key="i" class="aa-message" :class="m.role"><span>{{m.role==='user'?'你':'ASTRA'}}</span><AgentMessage v-if="m.role==='assistant'" :content="m.content"/><p v-else>{{m.content}}</p></div>
  <div v-if="brief" class="aa-brief"><span>DESIGN DIRECTION</span><div v-if="brief.mode" class="aa-intent-result"><Sparkles :size="11"/>{{brief.mode==='create'?'新建独立作品':'优化当前作品'}}<small>{{brief.scope==='selection'?'仅选中组件':'保留原稿 · 先预览'}}</small></div><strong>{{brief.title}}</strong><p>{{brief.style}}</p><ul><li v-for="o in brief.objectives" :key="o">{{o}}</li></ul></div>
  <div v-if="busy||tools.length" class="aa-run-card"><div><component :is="busy?LoaderCircle:CheckCircle2" :class="{spin:busy}" :size="15"/><strong>{{status}}</strong></div><p>第 {{round}} 轮 · {{completeTools}} 次工具执行完成</p><button @click="tab='execution'">查看执行与反馈 <ChevronRight :size="12"/></button></div>
  <div v-if="report" class="aa-evaluation" :class="{warning:report.errors.length||report.warnings.length}"><header><span><Activity :size="13"/>结构与运行检查</span><strong>{{report.score}}<small>/100</small></strong></header><div><span>{{report.metrics?.widgets||0}} 个组件</span><span>{{report.errors.length}} 项错误</span><span>{{report.warnings.length}} 项提醒</span></div><p>{{report.evidence}}</p><details v-if="report.errors.length||report.warnings.length"><summary>查看检查反馈</summary><ul><li v-for="(i,j) in [...report.errors,...report.warnings]" :key="j">{{i.message}}</li></ul></details></div>
  <p v-if="error" class="aa-error" role="alert"><AlertCircle :size="14"/>{{error}}</p><p v-if="conflict" class="aa-error" role="alert"><AlertCircle :size="14"/>原稿在生成期间发生了修改。请保留手动调整，重新生成草稿后应用。</p>
  <div v-if="result?.modified&&!applied" class="aa-apply"><button class="aa-primary" :disabled="!canApply" @click="apply"><component :is="applying?LoaderCircle:Check" :class="{spin:applying}" :size="14"/>{{applying?'正在保存…':'应用到画布'}}</button><button :disabled="busy||applying" @click="discard">收起草稿</button><small>应用后可通过工作台的撤销恢复原稿。</small></div><div v-if="applied" class="aa-applied"><CheckCircle2 :size="15"/>已应用，可继续提出局部修改。</div>
 </template>
 <template v-else-if="tab==='execution'"><div class="aa-section-intro"><span class="aa-eyebrow">EXECUTION & FEEDBACK</span><h3>每一次操作，都有依据。</h3><p>工具实际调用、返回结果与修正记录。点击展开参数和反馈。</p></div><div v-if="!tools.length" class="aa-empty"><Activity :size="25"/><p>开始一次创作后，执行记录会出现在这里。</p><small>{{agentTools.length}} 项原生设计器工具已就绪</small></div><article v-for="(t,i) in tools" :key="t.id" class="aa-tool" :class="t.state"><button @click="t.open=!t.open"><span class="aa-tool-number">{{String(i+1).padStart(2,'0')}}</span><span><strong>{{toolLabels[t.name]||t.name}}</strong><small>{{t.name}}</small></span><LoaderCircle v-if="t.state==='running'" class="spin" :size="14"/><Check v-else-if="t.state==='done'" :size="14"/><AlertCircle v-else :size="14"/><ChevronDown :size="12" :class="{expanded:t.open}"/></button><div v-if="t.open"><label>输入参数</label><pre>{{JSON.stringify(t.args,null,2)}}</pre><label>执行反馈 <span v-if="t.duration!==undefined">{{t.duration}} ms</span></label><pre v-if="t.result">{{JSON.stringify(t.result,null,2)}}</pre><p v-else>正在执行…</p></div></article><div v-if="tools.length" class="aa-execution-foot">{{usage.input.toLocaleString()}} 输入 / {{usage.output.toLocaleString()}} 输出 tokens<br/>最多 16 轮模型调用 · 最多 2 轮交付修正</div></template>
 <template v-else><div class="aa-section-intro"><span class="aa-eyebrow">MODEL CONNECTION</span><h3>选择你的创作引擎。</h3><p>国内外模型与自定义兼容接口。默认使用 OpenRouter / Claude Haiku 5.5。</p></div>
  <div v-if="isStaticHosting" class="aa-service-note"><ShieldCheck :size="19"/><strong>模型密钥由服务端保管</strong><p>GitHub Pages 提供完整编辑能力。智能创作需要 Worker 服务；可携带当前作品与本机素材进入完整服务版。</p><button class="aa-primary" :disabled="bridging" @click="bridge">{{bridging?'正在传递项目…':'携带项目打开智能创作'}}<ArrowUpRight :size="13"/></button></div>
  <div v-else-if="settings?.signInRequired" class="aa-service-note"><KeyRound :size="19"/><strong>登录后连接你的模型</strong><p>默认模型仅向工作空间所有者开放。其他用户可以配置自己的 API Key，密钥在服务端加密保存。</p><a class="aa-primary" :href="settings.signInUrl" target="_top">登录并继续 <ArrowUpRight :size="13"/></a><button class="aa-text-button" @click="loadSettings">已登录，刷新连接</button></div>
  <template v-else-if="!loadingSettings"><label class="aa-field">模型配置<select v-model="profileId" :disabled="busy||settingsBusy" aria-label="模型配置" @change="selectProfile"><option v-if="!settings?.profiles?.length" value="">请添加模型配置</option><option v-for="p in settings?.profiles||[]" :key="p.id" :value="p.id">{{p.name}} · {{providerById(p.provider)?.name}}</option></select></label><div v-if="profile" class="aa-profile-note"><span><ShieldCheck :size="11"/>{{profile.managed?'工作空间运行时 Secret':'服务端 AES-GCM 加密'}}</span><button v-if="!profile.managed" :disabled="busy" @click="editProfile(profile)">编辑</button><button v-if="!profile.managed" class="aa-icon" :disabled="busy" aria-label="删除模型配置" @click="removeProfile"><Trash2 :size="12"/></button></div><label class="aa-field">模型 ID<div class="aa-model-input"><input v-model="model" :disabled="busy" aria-label="模型 ID" list="aa-model-list" placeholder="选择或填写模型 ID"/><button :disabled="busy||settingsBusy||!profileId" aria-label="刷新模型列表" @click="fetchModels"><RefreshCw :size="13"/></button></div><datalist id="aa-model-list"><option v-for="m in models" :key="m.id" :value="m.id">{{m.name}}</option></datalist><small>可刷新厂商模型列表，也可手动输入。</small></label><button class="aa-outline aa-wide" :disabled="busy||settingsBusy||!profileId||!model" @click="testConnection"><component :is="settingsBusy?LoaderCircle:Play" :class="{spin:settingsBusy}" :size="13"/>{{settingsBusy?'正在连接…':'测试连接与工具调用'}}</button><p v-if="connection" class="aa-connection" :class="{failed:!connection.ok}"><component :is="connection.ok?CheckCircle2:AlertCircle" :size="14"/>{{connection.message}}</p><button class="aa-new-profile" :disabled="busy" @click="editProfile()"><Plus :size="14"/>添加其他厂商或自定义接口</button>
  <form v-if="formOpen" class="aa-profile-form" @submit.prevent="saveProfile"><div><strong>{{form.id?'编辑模型配置':'新的模型连接'}}</strong><button type="button" aria-label="关闭模型表单" @click="formOpen=false;form.apiKey=''"><X :size="14"/></button></div><label class="aa-field">模型厂商<select v-model="form.provider" aria-label="模型厂商" @change="changeProvider"><option v-for="p in providers" :key="p.id" :value="p.id">{{p.name}} · {{p.region}}</option></select></label><label class="aa-field">连接名称<input v-model="form.name" aria-label="连接名称" maxlength="60" placeholder="我的创作模型"/></label><label class="aa-field">API Base URL<input v-model="form.baseUrl" aria-label="API Base URL" required type="url" placeholder="https://…/v1"/></label><label class="aa-field">模型 ID<input v-model="form.model" aria-label="新配置模型 ID" required maxlength="180"/></label><label class="aa-field">API Key<input v-model="form.apiKey" aria-label="API Key" type="password" autocomplete="off" spellcheck="false" :placeholder="form.id?'留空保留已保存的密钥':'仅发送到服务端加密保存'"/><small>密钥不会写入项目、导出包或浏览器持久存储。更换接口后需重新填写。</small></label><button class="aa-primary aa-wide" :disabled="settingsBusy"><LoaderCircle v-if="settingsBusy" class="spin" :size="13"/>加密保存连接</button></form><p class="aa-settings-foot">连接其他厂商时使用该厂商的密钥。OpenRouter 的模型也可以来自国内外不同提供方。模型需支持函数工具调用。</p></template><div v-else class="aa-empty"><LoaderCircle class="spin" :size="20"/>正在读取安全配置…</div><p v-if="settingsError" class="aa-error" role="alert"><AlertCircle :size="13"/>{{settingsError}}</p>
 </template></div>
 <footer v-if="tab==='chat'" class="aa-composer"><div v-if="busy" class="aa-live-status" role="status"><LoaderCircle class="spin" :size="12"/><span>{{status}}</span><button aria-label="停止生成" @click="abort?.abort()"><Square :size="10"/>停止</button></div><p v-if="busy&&notice" class="aa-notice">{{notice}}</p><div class="aa-compose-options"><span class="aa-auto-intent"><Sparkles :size="11"/>模型自动判断意图</span><span v-if="selectedIds.length" class="aa-selection-context">已选 {{selectedIds.length}} 项</span><span><ShieldCheck :size="10"/>先预览，后应用</span></div><div class="aa-prompt-box"><textarea ref="input" v-model="prompt" :disabled="busy" aria-label="描述你想要的大屏" rows="3" maxlength="3000" :placeholder="'描述业务、风格和重点…\n也可以选中组件，提出精修要求。'" @keydown.enter.exact="!$event.isComposing&&($event.preventDefault(),run())"></textarea><div><button class="aa-model-chip" @click="tab='settings'"><span></span>{{isStaticHosting?'连接智能服务':model===DEFAULT_MODEL?'Claude Haiku 5.5':model||'选择模型'}}<ChevronDown :size="10"/></button><button class="aa-send" :disabled="busy||!prompt.trim()||bridging" aria-label="开始智能创作" @click="run"><LoaderCircle v-if="bridging" class="spin" :size="16"/><ArrowUp v-else :size="17"/></button></div></div><small>Enter 发送 · Shift + Enter 换行 · 生成的数据为演示用途</small></footer>
</aside></template>
